<template><view class="page"><view class="custom-nav" :style="{ paddingTop: statusBarHeight + 'px' }"><view class="nav-row"><text class="nav-icon" @click="goBack">&#x2190;</text><text class="nav-title">&#x6570;&#x72EC;</text><text class="nav-icon" @click="newGame">&#x1F504;</text></view></view><view class="content"><view class="difficulty-row"><view class="diff-btn" :class="{active: diff==='easy'}" @click="diff='easy';newGame()">&#x7B80;&#x5355;</view><view class="diff-btn" :class="{active: diff==='medium'}" @click="diff='medium';newGame()">&#x4E2D;&#x7B49;</view><view class="diff-btn" :class="{active: diff==='hard'}" @click="diff='hard';newGame()">&#x56F0;&#x96BE;</view></view><view class="timer-row"><text class="timer-text">{{ formattedTime }}</text><text class="hint-btn" @click="getHint">&#x1F4A1; &#x63D0;&#x793A;</text></view><view class="sudoku-grid"><view class="sudoku-cell" v-for="(cell, idx) in displayBoard" :key="idx" :class="{given: cell.given, selected: selected===idx, conflict: cell.conflict, hint: cell.isHint}" @click="selectCell(idx)"><text>{{ cell.val || '' }}</text></view></view><view class="numpad"><view class="num-btn" v-for="n in 9" :key="n" @click="inputNum(n)">{{n}</view><view class="num-btn erase" @click="inputNum(0)">&#x2715;</view></view></view></view></template><script setup>import { ref, computed, onMounted, onUnmounted } from "vue"
const statusBarHeight = uni.getSystemInfoSync().statusBarHeight || 20
const diff = ref("easy")
const board = ref([])
const solution = ref([])
const selected = ref(-1)
const seconds = ref(0)
const formattedTime = computed(function() { var m = Math.floor(seconds.value/60); var s = seconds.value%60; return (m<10?"0":"")+m+":"+(s<10?"0":"")+s })
var timer = null
const displayBoard = computed(function() { return board.value.map(function(c) { return { val: c.val || "", given: c.given || false, conflict: c.conflict || false, isHint: c.isHint || false } }) })
function goBack() { uni.navigateBack(); clearInterval(timer) }
function newGame() { clearInterval(timer); seconds.value = 0; selected.value = -1; var sol = generateSolution(); solution.value = sol.slice(); var puzzle = sol.slice(); var remove = diff.value==="easy"?30:diff.value==="medium"?45:55; for (var i = 0; i < remove; i++) { var idx = Math.floor(Math.random()*81); puzzle[idx] = 0 } board.value = puzzle.map(function(v) { return { val: v || "", given: v > 0, conflict: false, isHint: false } }); timer = setInterval(function() { seconds.value++ }, 1000) }
function generateSolution() { var b = Array(81).fill(0); fillBoard(b); return b }
function fillBoard(b) { for (var i = 0; i < 81; i++) { if (b[i] === 0) { var nums = [1,2,3,4,5,6,7,8,9].sort(function(){return Math.random()-0.5}); for (var j = 0; j < nums.length; j++) { if (isValid(b, i, nums[j])) { b[i] = nums[j]; if (!b.some(function(c){return !c}) || fillBoard(b)) return true; b[i] = 0 } } return false } } return true }
function isValid(b, idx, num) { var r = Math.floor(idx/9), c = idx%9; for (var i = 0; i < 9; i++) { if (b[r*9+i] === num || b[i*9+c] === num) return false } var br = Math.floor(r/3)*3, bc = Math.floor(c/3)*3; for (var i = br; i < br+3; i++) for (var j = bc; j < bc+3; j++) if (b[i*9+j] === num) return false; return true }
function selectCell(idx) { if (board.value[idx].given) return; selected.value = idx }
function inputNum(n) { if (selected.value < 0) return; board.value[selected.value].val = n || ""; board.value[selected.value].isHint = false; checkConflicts() }
function checkConflicts() { board.value.forEach(function(c, i) { c.conflict = false; if (!c.val) return; var r = Math.floor(i/9), col = i%9; for (var j = 0; j < 9; j++) { var idx1 = r*9+j, idx2 = j*9+col; if (idx1 !== i && board.value[idx1].val === c.val) c.conflict = true; if (idx2 !== i && board.value[idx2].val === c.val) c.conflict = true } var br = Math.floor(r/3)*3, bc = Math.floor(col/3)*3; for (var ii = br; ii < br+3; ii++) for (var jj = bc; jj < bc+3; jj++) { var idx3 = ii*9+jj; if (idx3 !== i && board.value[idx3].val === c.val) c.conflict = true } }) }
function getHint() { var empty = []; board.value.forEach(function(c,i){ if(!c.val) empty.push(i) }); if (!empty.length) return; var idx = empty[Math.floor(Math.random()*empty.length)]; board.value[idx].val = solution.value[idx]; board.value[idx].isHint = true; selected.value = idx; checkConflicts() }
onMounted(function() { if (!uni.getStorageSync("isLoggedIn")) { uni.reLaunch({ url: "/pages/login/login" }); return } newGame() })
onUnmounted(function() { clearInterval(timer) })
</script><style scoped>.page{min-height:100vh;background:#f5f7fb}.custom-nav{background:linear-gradient(135deg,#8b5cf6,#7c3aed);width:100%}.nav-row{height:88rpx;display:flex;align-items:center;padding:0 24rpx}.nav-icon{width:72rpx;text-align:center;font-size:44rpx;color:#fff;font-weight:700;flex-shrink:0}.nav-title{flex:1;text-align:center;font-size:32rpx;color:#fff;font-weight:600}.content{padding:24rpx}.difficulty-row{display:flex;gap:12rpx;margin-bottom:16rpx}.diff-btn{flex:1;padding:16rpx;text-align:center;background:#fff;border-radius:12rpx;font-size:26rpx;color:#666}.diff-btn.active{background:linear-gradient(135deg,#8b5cf6,#7c3aed);color:#fff}.timer-row{display:flex;justify-content:space-between;align-items:center;margin-bottom:16rpx}.timer-text{font-size:32rpx;color:#8b5cf6;font-weight:700;font-family:monospace}.hint-btn{font-size:26rpx;color:#8b5cf6;background:#fff;padding:8rpx 16rpx;border-radius:8rpx}.sudoku-grid{display:grid;grid-template-columns:repeat(9,1fr);gap:1rpx;background:#334155;border-radius:8rpx;padding:2rpx}.sudoku-cell{width:100%;aspect-ratio:1;background:#fff;display:flex;align-items:center;justify-content:center;font-size:28rpx;font-weight:600;color:#1e293b}.sudoku-cell.given{background:#eef2ff;color:#4f46e5}.sudoku-cell.selected{background:#ddd6fe}.sudoku-cell.conflict{background:#fee2e2;color:#ef4444}.sudoku-cell.hint{background:#fef3c7;color:#f59e0b}.numpad{display:grid;grid-template-columns:repeat(5,1fr);gap:8rpx;margin-top:16rpx}.num-btn{padding:20rpx;text-align:center;background:#fff;border-radius:12rpx;font-size:30rpx;font-weight:600;color:#333;box-shadow:0 2rpx 8rpx rgba(0,0,0,.04)}.num-btn.erase{color:#ef4444}</style>